          "title": "From relative position to relative velocity",
          "intrinsic_badge": "HARD",
          "inferential_jump": "Subtract two relative-position equations before dividing by a common time interval.",
          "entry_assumptions": [
            "Can construct relative position and interpret displacement over time."
          ],
          "teaching_path": [
            {
              "id": "RV-1",
              "action": "Write relative position at t1 and t2.",
              "why_valid": "Apply the same relation at both instants.",
              "inputs": [
                "REL-RELATIVE-POSITION"
              ],
              "output": "r_A/B(t2) - r_A/B(t1) = [r_A(t2)-r_A(t1)] - [r_B(t2)-r_B(t1)]",
              "role": "DECLARE"
            },
            {
              "id": "RV-2",
              "action": "Group the displacement changes.",
              "why_valid": "Vector subtraction distributes through the two same-time equations.",
              "inputs": [],
              "output": "Delta r_A/B = Delta r_A - Delta r_B",
              "role": "TRANSFORM"
            },
            {
              "id": "RV-3",
              "action": "Divide each term by the same nonzero Delta t.",
              "why_valid": "Each quotient is average velocity over that interval.",
              "inputs": [],
              "output": "vbar_A/B = vbar_A - vbar_B",
              "role": "TRANSFORM"
            },
            {
              "id": "RV-4",
              "action": "For this constant-velocity teaching case, use v for each constant average.",
              "why_valid": "No instantaneous calculus limit is needed in this case.",
              "inputs": [],
              "output": "v_A/B = v_A - v_B",
              "role": "DECLARE"
            }
          ],
